CREATE TABLE IF NOT EXISTS businesses ( id TEXT PRIMARY KEY, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'new' CHECK (status IN ('new','assistance','clarifying','ready','approved','not_eligible','declined')), published_at TEXT, slug TEXT UNIQUE, category TEXT NOT NULL CHECK (category IN ('home','micro')), name TEXT NOT NULL, kind TEXT NOT NULL, type_label TEXT, summary TEXT, description TEXT, city TEXT, area TEXT, website TEXT, order_url TEXT, instagram TEXT, facebook TEXT, tiktok TEXT, public_email TEXT, public_phone TEXT, stall_display TEXT, stall_roof TEXT, stall_colors TEXT, stall_valance TEXT, stall_chalk TEXT, first_name TEXT NOT NULL, license_status TEXT NOT NULL CHECK (license_status IN ('ready','unsure','started','not_started','not_required')), wants_help INTEGER NOT NULL DEFAULT 0, independent_ok INTEGER NOT NULL DEFAULT 0, notes TEXT NOT NULL DEFAULT '' );
CREATE INDEX IF NOT EXISTS idx_businesses_status ON businesses(status);
CREATE TABLE IF NOT EXISTS photos ( id TEXT PRIMARY KEY, business_id TEXT NOT NULL REFERENCES businesses(id) ON DELETE CASCADE, r2_key TEXT NOT NULL, alt TEXT NOT NULL DEFAULT '', sort INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL );
CREATE INDEX IF NOT EXISTS idx_photos_business ON photos(business_id);
CREATE TABLE IF NOT EXISTS stories ( id TEXT PRIMARY KEY, created_at TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','published','archived')), author TEXT NOT NULL, business TEXT, contact TEXT NOT NULL, title TEXT NOT NULL, body TEXT NOT NULL );
CREATE TABLE IF NOT EXISTS settings ( key TEXT PRIMARY KEY, value TEXT NOT NULL );
CREATE TABLE IF NOT EXISTS audit ( id INTEGER PRIMARY KEY AUTOINCREMENT, at TEXT NOT NULL, business_id TEXT, action TEXT NOT NULL, detail TEXT );
